int git_object__from_raw(
        git_object **object_out,
        const char *data,
        size_t size,
        git_otype type)
{
        git_object_def *def;
        git_object *object;
        size_t object_size;
        int error;

        assert(object_out);
        *object_out = NULL;

        /* Validate type match */
        if (type != GIT_OBJ_BLOB && type != GIT_OBJ_TREE && type != GIT_OBJ_COMMIT && type != GIT_OBJ_TAG) {
                giterr_set(GITERR_INVALID, "the requested type is invalid");
                return GIT_ENOTFOUND;
        }

        if ((object_size = git_object__size(type)) == 0) {
                giterr_set(GITERR_INVALID, "the requested type is invalid");
                return GIT_ENOTFOUND;
        }

        /* Allocate and initialize base object */
        object = git__calloc(1, object_size);
        GITERR_CHECK_ALLOC(object);
        object->cached.flags = GIT_CACHE_STORE_PARSED;
        object->cached.type = type;
        git_odb_hash(&object->cached.oid, data, size, type);

        /* Parse raw object data */
        def = &git_objects_table[type];
        assert(def->free && def->parse_raw);

        if ((error = def->parse_raw(object, data, size)) < 0) {
                def->free(object);
                return error;
        }

        git_cached_obj_incref(object);
        *object_out = object;

        return 0;
}

int git_object__from_odb_object(
        git_object **object_out,
        git_repository *repo,
        git_odb_object *odb_obj,
        git_otype type)
{
        int error;
        size_t object_size;
        git_object_def *def;
        git_object *object = NULL;

        assert(object_out);
        *object_out = NULL;

        /* Validate type match */
        if (type != GIT_OBJ_ANY && type != odb_obj->cached.type) {
                giterr_set(GITERR_INVALID,
                        "the requested type does not match the type in the ODB");
                return GIT_ENOTFOUND;
        }

        if ((object_size = git_object__size(odb_obj->cached.type)) == 0) {
                giterr_set(GITERR_INVALID, "the requested type is invalid");
                return GIT_ENOTFOUND;
        }

        /* Allocate and initialize base object */
        object = git__calloc(1, object_size);
        GITERR_CHECK_ALLOC(object);

        git_oid_cpy(&object->cached.oid, &odb_obj->cached.oid);
        object->cached.type = odb_obj->cached.type;
        object->cached.size = odb_obj->cached.size;
        object->repo = repo;

        /* Parse raw object data */
        def = &git_objects_table[odb_obj->cached.type];
        assert(def->free && def->parse);

        if ((error = def->parse(object, odb_obj)) < 0)
                def->free(object);
        else
                *object_out = git_cache_store_parsed(&repo->objects, object);

        return error;
}

void git_object__free(void *obj)
{
        git_otype type = ((git_object *)obj)->cached.type;

        if (type < 0 || ((size_t)type) >= ARRAY_SIZE(git_objects_table) ||
                !git_objects_table[type].free)
                git__free(obj);
        else
                git_objects_table[type].free(obj);
}

